INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein NAS immer einen Server ersetzt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Spezialisiert auf Speicherung"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
